        token.excludeFromFee(user);
        logs = vm.getRecordedLogs();
        console.log("(iii) AFTER-Trigger: events emitted =", logs.length);
        if (logs.length == 0) {
            console.log("(iv) COMPARISON: expected >= 1 event, observed 0 -> EVENT MISSING (vulnerable)");
